//! The encoder-plus-head execution plan as pure data: kernel names and
//! buffer roles, before any CUDA symbol or weight pointer is resolved.
//! The encoder half is generated by the family core from the admitted
//! structure; the task-head half stays here. Keeping the plan pure lets
//! CPU fixtures pin the exact step sequence.

use omni_modernbert::plan::{
    EncoderPlanOptions, PlanAnchor, PlanArg, PlanStep, ScratchSlot,
    encoder_plan as family_encoder_plan,
};
use omni_modernbert::structure::ModernBertStructure;

/// Scratch buffers the plan addresses; allocation lives in the executor.
#[derive(Clone, Copy)]
pub enum Scratch {
    Ids,
    Lens,
    Types,
    X,
    Y,
    Qkv,
    O,
    G,
    Ff,
}

impl Scratch {
    pub fn name(self) -> &'static str {
        match self {
            Self::Ids => "ids",
            Self::Lens => "lens",
            Self::Types => "types",
            Self::X => "x",
            Self::Y => "y",
            Self::Qkv => "qkv",
            Self::O => "o",
            Self::G => "g",
            Self::Ff => "ff",
        }
    }
}

#[derive(Clone)]
pub enum PlannedArg {
    Weight(String),
    Scratch(Scratch),
}

#[derive(Clone)]
pub enum PlannedStep {
    Launch {
        kernel: String,
        args: Vec<PlannedArg>,
    },
    Dump {
        name: String,
        slot: Scratch,
        bf: bool,
    },
}

impl PlannedStep {
    /// One-line canonical rendering used by the plan fixtures.
    pub fn render(&self) -> String {
        match self {
            Self::Launch { kernel, args } => {
                let mut line = format!("launch {kernel}");
                for arg in args {
                    line.push(' ');
                    line.push_str(&match arg {
                        PlannedArg::Weight(name) => name.clone(),
                        PlannedArg::Scratch(slot) => slot.name().to_string(),
                    });
                }
                line
            }
            Self::Dump { name, slot, bf } => {
                format!("dump {name} {} {}", slot.name(), u8::from(*bf))
            }
        }
    }
}

fn map_arg(arg: PlanArg) -> PlannedArg {
    match arg {
        PlanArg::Weight(name) => PlannedArg::Weight(name),
        PlanArg::Scratch(slot) => PlannedArg::Scratch(match slot {
            ScratchSlot::Ids => Scratch::Ids,
            ScratchSlot::Lens => Scratch::Lens,
            ScratchSlot::Types => Scratch::Types,
            ScratchSlot::X => Scratch::X,
            ScratchSlot::Y => Scratch::Y,
            ScratchSlot::Qkv => Scratch::Qkv,
            ScratchSlot::O => Scratch::O,
            ScratchSlot::Gate => Scratch::G,
        }),
    }
}

/// The execution plan for the admitted Laya profile: the family encoder
/// plan with this bundle's debug dumps hooked to the sequence anchors,
/// followed by the task head's two transformer layers. The readout tail
/// stays with eager launches at inference time.
pub fn plan_encoder(structure: &ModernBertStructure, original_rope: bool) -> Vec<PlannedStep> {
    let mut steps = Vec::new();
    for step in family_encoder_plan(structure, &EncoderPlanOptions { original_rope }) {
        match step {
            PlanStep::Launch { kernel, args } => steps.push(PlannedStep::Launch {
                kernel,
                args: args.into_iter().map(map_arg).collect(),
            }),
            PlanStep::Anchor(PlanAnchor::AfterEmbed) => steps.push(PlannedStep::Dump {
                name: "embedding".to_string(),
                slot: Scratch::X,
                bf: false,
            }),
            PlanStep::Anchor(PlanAnchor::LayerEnd(i)) => {
                if [0, 1, 2, 27].contains(&i) {
                    steps.push(PlannedStep::Dump {
                        name: format!("encoder{i}_residual"),
                        slot: Scratch::X,
                        bf: false,
                    });
                    steps.push(PlannedStep::Dump {
                        name: format!("encoder{i}_normalized"),
                        slot: Scratch::Y,
                        bf: true,
                    });
                }
            }
            PlanStep::Anchor(PlanAnchor::AfterEncoder) => {}
        }
    }
    steps.extend(head_plan());
    steps
}

fn head_plan() -> Vec<PlannedStep> {
    let steps = std::cell::RefCell::new(Vec::new());
    let weight = |name: &str| PlannedArg::Weight(name.to_string());
    let scratch = |slot: Scratch| PlannedArg::Scratch(slot);
    let call = |kernel: &str, args: &[PlannedArg]| {
        steps.borrow_mut().push(PlannedStep::Launch {
            kernel: kernel.to_string(),
            args: args.to_vec(),
        });
    };
    let attention = |label: &str| format!("attn_{label}");
    for i in 0..2 {
        let p = format!("head.layers.{i}");
        let w = |n: &str| weight(&format!("{p}.{n}"));
        call(
            "ln_bias",
            &[
                scratch(Scratch::X),
                scratch(Scratch::Y),
                w("norm1.weight"),
                w("norm1.bias"),
                scratch(Scratch::Y),
            ],
        );
        call(
            "head_in",
            &[
                scratch(Scratch::Y),
                w("self_attn.in_proj_weight"),
                w("self_attn.in_proj_bias"),
                scratch(Scratch::Qkv),
            ],
        );
        call(
            &attention("full"),
            &[
                scratch(Scratch::Qkv),
                scratch(Scratch::Lens),
                scratch(Scratch::O),
            ],
        );
        call(
            "head_out",
            &[
                scratch(Scratch::O),
                w("self_attn.out_proj.weight"),
                w("self_attn.out_proj.bias"),
                scratch(Scratch::Y),
            ],
        );
        call(
            "addln_bias",
            &[
                scratch(Scratch::X),
                scratch(Scratch::Y),
                w("norm2.weight"),
                w("norm2.bias"),
                scratch(Scratch::Y),
            ],
        );
        call(
            "ffn1",
            &[
                scratch(Scratch::Y),
                w("linear1.weight"),
                w("linear1.bias"),
                scratch(Scratch::Ff),
            ],
        );
        call(
            "ffn2",
            &[
                scratch(Scratch::Ff),
                w("linear2.weight"),
                w("linear2.bias"),
                scratch(Scratch::Y),
            ],
        );
        call("residual", &[scratch(Scratch::X), scratch(Scratch::Y)]);
    }
    steps.into_inner()
}

/// Renders a full plan, one step per line, for fixture comparison.
pub fn render_plan(plan: &[PlannedStep]) -> String {
    plan.iter()
        .map(PlannedStep::render)
        .collect::<Vec<_>>()
        .join("\n")
        + "\n"
}
